const services={dog:[['Комплексный груминг','Купание, сушка и стрижка с учётом породы и ваших пожеланий. Подходит собакам мелких, средних и крупных пород. Состав комплекса уточнит администратор.'],['Экспресс-линька','Вычёсывание лишнего подшёрстка и уход за шерстью. Подберём процедуру с учётом типа шерсти вашего питомца.'],['Тримминг','Уход за жёсткой шерстью. Мастер поможет определить подходящий объём работы и регулярность посещений.'],['SPA и гигиена','SPA-процедуры, купание, уход за когтями и ушами, гигиена полости рта. Можно обсудить как отдельные услуги.']],cat:[['Комплексный уход','Купание и уход за шерстью кошек. Для длинношёрстных котов в Яндекс Картах указан комплекс 5 200 ₽. Актуальную стоимость подтвердит администратор.'],['Вычёсывание и экспресс-линька','Удаление лишнего подшёрстка и уход за шерстью. Для очень крупных котов более 8 кг на Яндекс Картах указан комплекс с когтями, ушами и глазами — 4 800 ₽.'],['Гигиенический уход','Уход за когтями и ушами. Расскажите администратору об особенностях вашего кота, чтобы подобрать подходящие процедуры.']]};
function renderServices(pet){document.querySelector('#service-items').innerHTML=services[pet].map((s,i)=>`<details ${i===0?'open':''}><summary><span>0${i+1}</span><b>${s[0]}</b><span aria-hidden="true">+</span></summary><p>${s[1]}</p></details>`).join('');}renderServices('dog');document.querySelectorAll('[data-pet]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-pet]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});renderServices(b.dataset.pet)}));
const dialog=document.querySelector('#booking');document.querySelectorAll('.book').forEach(b=>b.addEventListener('click',()=>dialog.showModal()));document.querySelector('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()});const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));menu.setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');document.querySelector('nav').classList.toggle('open',open)});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Открыть меню');document.querySelector('nav').classList.remove('open')}));
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.12});document.querySelectorAll('.reveal').forEach(e=>observer.observe(e));

// Revision 3: restrained dimensional motion, only for precise pointers.
if(matchMedia('(hover: hover) and (prefers-reduced-motion: no-preference)').matches){document.querySelectorAll('.visit-card,.seal').forEach(el=>{el.addEventListener('pointermove',e=>{const r=el.getBoundingClientRect();el.style.rotate=`${(e.clientX-r.left-r.width/2)/r.width*3}deg`;el.style.translate=`0 ${(e.clientY-r.top-r.height/2)/r.height*-5}px`});el.addEventListener('pointerleave',()=>{el.style.rotate='0deg';el.style.translate='0 0'})});}
